    "content": "绿色金融走向深水区，资产组合碳管理能力仍待突破。 南方周末研究员 康华 责任编辑：孙孝文 绿色金融发展到2026年，评价一家机构绿色金融实践的尺度，已经发生变化。 2026年1月，中国人民银行将节能改造、绿色升级、能源绿色低碳转型等具有直接碳减排效应的项目纳入碳减排支持工具支持领域，政策激励从支持绿色产业进一步延伸至传统产业的绿色改造，并更加突出资金的实际减碳效果。 2025年末印发的《企业可持续披露准则第1号——气候（试行）》，将气候风险、情景分析、范围三排放和融资排放纳入系统化披露框架，明确提出业务涉及资产管理…"
