    "description": "（北京讯）中国首个科技法学院在河北省雄安新区成立，聚焦人工智能、自动驾驶、新材料、绿色低碳冶金、空天信息、关键矿产等战略技术与未来产业，培养复合型人才。 据央视新闻报道，北京科技大学科技法学院11月7日在雄安新区正式成立。学院内设知识产权、科技法、科技政策、法学基础四个教学科研机构。北科大1952年建校，是中国教育部直属的“双一流”高校。 据北科大微信公号，作为中国首家实体化运行的高校科技法学教学科研机构，学院在雄安招收知识产权本科专业…",
    "content": "（北京讯）中国首个科技法学院在河北省 雄安新区 成立，聚焦人工智能、自动驾驶、新材料、绿色低碳冶金、空天信息、关键矿产等战略技术与未来产业，培养复合型人才。 据央视新闻报道，北京科技大学科技法学院11月7日在雄安新区正式成立。学院内设知识产权、科技法、科技政策、法学基础四个教学科研机构。北科大1952年建校，是中国教育部直属的“双一流”高校。 据北科大微信公号，作为中国首家实体化运行的高校科技法学教学科研机构，学院在雄安招收知识产权本科专业（工法复合）学生和法律硕士（非法学）知识产权方向研究生。 雄安新区距离北京1…"
