    "content": "菲律宾外交部罕见公开批评本国部分政府官员就中国及南中国海问题发表的言论，警告这些言论可能损害菲律宾的国际公信力，削弱外交谈判立场，并强调国家对外政策必须遵循总统制定的方向。 菲律宾外交部星期天（11月8日）发表声明，批评部分官员近期将海上事件的证据记录、公开言论与正式外交混为一谈，但未点名涉及哪些官员，也没有列举具体言论。 声明指出，公开南中国海争议海域的事件，有助于确立事实、反击虚假信息及争取国际关注，但“透明是一种工具，本身并不是战略”。 菲外交部强调，公布影像或塑造网络舆论，本身既无法在海上形成实际威慑，也不…"
