    "pub_date": "2026-11-08 18:58:00",
    "author": "",
    "description": "新华社德黑兰11月8日电（记者刁慧琳 沙达提）据伊朗法尔斯通讯社8日报道，伊朗伊斯兰革命卫队发言人穆赫比当天表示，美国无法通过组建“铁门”特遣部队计划实现其给伊朗施加经济压力的目的。 穆赫比说，“铁门”计划“不过是文字游戏”，美国无法通过这一计划实现其给伊朗施加巨大经济压力的目的，伊朗经济不会崩溃。 美军中央司令部7日在社交媒体发布消息说，中央司令部司令库珀已下令组建一支名为“铁门”的特遣部队。该特遣部队将与美国其他政府机构开展协作，以…",
    "content": "新华社德黑兰11月8日电（记者刁慧琳 沙达提）据伊朗法尔斯通讯社8日报道，伊朗伊斯兰革命卫队发言人穆赫比当天表示，美国无法通过组建“铁门”特遣部队计划实现其给伊朗施加经济压力的目的。 穆赫比说，“铁门”计划“不过是文字游戏”，美国无法通过这一计划实现其给伊朗施加巨大经济压力的目的，伊朗经济不会崩溃。 美军中央司令部7日在社交媒体发布消息说，中央司令部司令库珀已下令组建一支名为“铁门”的特遣部队。该特遣部队将与美国其他政府机构开展协作，以防止伊朗利用陆路等方式跨境运输先进武器及其他物资。“铁门”特遣部队由约20名文职…"
