    "title": "专访丨人工智能是高效工具，但新闻决定权仍属于人——访法新社社长弗里",
    "link": "http://www.news.cn/20261108/8eed927a0a404261a9db1a701e61c1b7/c.html",
    "pub_date": "2026-11-08 18:29:40",
    "author": "",
    "description": "新华社北京11月8日电 专访｜人工智能是高效工具，但新闻决定权仍属于人——访法新社社长弗里 新华社记者李言 陈望琪 “人工智能非常擅长回顾过去、总结既往事件，但不擅长报道新发生的事实。”法新社社长兼首席执行官法布里斯·弗里在出席第七届世界媒体峰会期间接受新华社记者专访时表示，人工智能是新闻生产的高效工具，但编辑室的最终决定权仍属于人，而非人工智能。 弗里认为，在寻找新闻线索、采访、判断新闻价值、决定是否披露敏感信息等环节，人工智能均无法…",
    "content": "新华社北京11月8日电 专访｜人工智能是高效工具，但新闻决定权仍属于人——访法新社社长弗里 新华社记者李言 陈望琪 “人工智能非常擅长回顾过去、总结既往事件，但不擅长报道新发生的事实。”法新社社长兼首席执行官法布里斯·弗里在出席第七届世界媒体峰会期间接受新华社记者专访时表示，人工智能是新闻生产的高效工具，但编辑室的最终决定权仍属于人，而非人工智能。 弗里认为，在寻找新闻线索、采访、判断新闻价值、决定是否披露敏感信息等环节，人工智能均无法替代记者。 在突发新闻报道中，人类不可替代。寻找消息来源、理解事件背景等工作“高…"
