    "description": "第九届进博会期间，澎湃新闻推出《实测进博：全球顶级展会何以越办越好》系列短视频。短片聚焦场馆医疗保障。针对展会现场常见的十大类病症，医疗保障团队制定了配套标准化处置流程。巡场医护、医疗站点、120急救三方联动闭环，把过去零散、被动的临场急救，变成了一套可复用的标准化体系，为大型展会应急保障留下成熟样本。",
    "content": "第九届进博会期间，澎湃新闻推出《实测进博：全球顶级展会何以越办越好》系列短视频。短片聚焦场馆医疗保障。针对展会现场常见的十大类病症，医疗保障团队制定了配套标准化处置流程。巡场医护、医疗站点、120急救三方联动闭环，把过去零散、被动的临场急救，变成了一套可复用的标准化体系，为大型展会应急保障留下成熟样本。"
