    "content": "新华社利雅得11月8日电（记者王海洲）沙特阿拉伯能源部8日发表声明说，位于沙特首都利雅得阿卜杜拉国王金融区的一栋沙特阿美石油公司行政办公楼当天遭到袭击，建筑轻微损坏，未造成人员伤亡。 声明说，袭击发生后，弹片坠落造成该办公楼建筑局部受损。相关部门已迅速赶赴现场处置，并采取必要措施。 沙特主导的多国联军发言人图尔基·马利基8日在社交媒体发文说，沙特防空系统当天拦截并摧毁了也门胡塞武装向利雅得发射的两枚弹道导弹，以及向沙特东部地区发射的一枚弹道导弹。此外，沙特防空系统当天还在利雅得地区和沙特南部地区拦截并摧毁了两枚巡航…"
