    "content": "索尼2026财年第二季度财报电话会议中，首次就PlayStation 6的开发进展作出较为明确的官方说明。公司首席财务官指出，下一代主机平台的研发工作正稳步推进，整体节奏符合既定规划。按照当前安排，相关投入将集中于2027财年（即2027年4月至2028年3月），并力争在该财年内实现关键性突破与实质性进展。此外，索尼已与主要供应商完成协商，确定了下一财年所需内存芯片的采购规模，该数量足以支撑预期中的硬���出货目标。（新浪财经）"
