    "content": "据广东阳江广播电视台消息，11月8日，阳江海陵湾新区揭牌活动举行，标志着新区建设迈入全新阶段。 消息称，当前，海洋经济、湾区经济已成为全国、全省高质量发展的核心方向。为深入贯彻落实党中央、国务院关于整合优化经济功能区、优化区域发展布局的重大战略部署，立足阳江“承接大湾区辐射、打造西海岸重要支点”战略定位，进一步整合滨海资源、优化平台布局、破解区域分散发展等问题，经省委、省政府批复同意，原阳江滨海新区更名为阳江海陵湾新区，代管海陵经济开发试验区，管辖平冈镇、闸坡镇。 新区规划总面积505.9平方公里，户籍人口约20万…"
