    "author": "",
    "description": "11月初，吉尔吉斯斯坦巴特肯州的高原矿区，坡陡谷深，寒风凛冽。一批柳工挖掘机伸缩臂膀，开挖土方，冻土虽硬，一斗一斗照样啃得动。连续数月，海拔约4000米的环境下，机器没趴窝，服务没断线，当地司机和项目方直呼“实力过硬”！",
