    "description": "中国影视演员佟丽娅当选新疆文艺志愿者协会副主席。 据“新疆文联”微信公众号消息，新疆文艺志愿者协会成立大会暨第一次会员代表大会上星期四（11月5日）在乌鲁木齐闭幕，佟丽娅当选新疆文艺志愿者协会副主席。 佟丽娅通过视频称，由于工作的原因，无法到现场。她说：“我们要多走进乡村、牧区，用心倾听群众，用接地气的作品讲好温暖、真实的新疆故事。” 佟丽娅曾出演多部影视剧，代表作包括《北京爱情故事》等。 据“新疆日报”微信公众号消息，中国演员陈建斌当…",
    "content": "中国影视演员佟丽娅当选新疆文艺志愿者协会副主席。 据“新疆文联”微信公众号消息，新疆文艺志愿者协会成立大会暨第一次会员代表大会上星期四（11月5日）在乌鲁木齐闭幕，佟丽娅当选新疆文艺志愿者协会副主席。 佟丽娅通过视频称，由于工作的原因，无法到现场。她说：“我们要多走进乡村、牧区，用心倾听群众，用接地气的作品讲好温暖、真实的新疆故事。” 佟丽娅曾出演多部影视剧，代表作包括《北京爱情故事》等。 据“新疆日报”微信公众号消息，中国演员陈建斌当选了新疆文艺志愿者协会主席。陈建斌以在电视剧《甄嬛传》中饰演雍正帝而广为人知。 …"
