    "content": "新华社北京11月8日电 题：红色新闻人的浴血征程 新华社记者李秉宣 江西瑞金，中央革命根据地历史博物馆展陈着一张泛黄的报纸残片。它纵23厘米，横44厘米，仅存整张报纸的三分之一。 这是《红色中华》报第264期，1935年1月21日出版，是目前已知的在中央苏区出版的最后一期《红色中华》报。 这是中央革命根据地历史博物馆展陈的1935年1月21日在中央苏区出版的第264期《红色中华》报报纸残片（2026年4月28日摄，手机照片）。新华社记者 李秉宣 摄 这一天，是列宁逝世11周年纪念日。报纸头版刊登的列宁像和“列宁的教…"
