    "content": "编者按：九十五年前，1931年11月7日，新华社的前身红色中华通讯社在瑞金成立。从那时起，新华社追随党中央的步伐，从瑞金、延安、西柏坡到香山、宣武门，一路走来，新华社的摄影队伍“以影像著史”，为国存照，担负着为党和人民记录时代风云的重任，将历史的宏大叙事凝固在取景框里，成为众所周知的“国家摄影队”。 今天是记者节，“我在现场”栏目把“国家摄影队”请到台前，他们和照片背后的故事将在这里一一展开。这是他们的“在场”证明，也是这支“国家队”一直持续的影像长征。 2026年11月7日 新华社刚刚迎来自己的95岁生日 今天，…"
