    "title": "阿联酋海岸警卫队从阿曼湾一起火货船上救出22人",
    "link": "http://www.news.cn/20261108/726aa625dafc42a881fcacf029a5f6da/c.html",
    "pub_date": "2026-11-08 16:23:27",
    "author": "",
    "description": "新华社阿布扎比11月8日电（记者温新年）据阿联酋通讯社8日报道，阿联酋海岸警卫队当天宣布从阿曼湾一艘发生火灾的货船上救出全部22名船员，获救人员身体状况稳定。 报道说，阿联酋海岸警卫队接到船员关于发生火灾的报告后，立即派出专业救援队伍展开行动。获救人员均来自阿拉伯国家。救援人员在提供必要的急救措施后，已将他们移交给有关部门。 起火原因及船只受损情况尚未公布。",
    "content": "新华社阿布扎比11月8日电（记者温新年）据阿联酋通讯社8日报道，阿联酋海岸警卫队当天宣布从阿曼湾一艘发生火灾的货船上救出全部22名船员，获救人员身体状况稳定。 报道说，阿联酋海岸警卫队接到船员关于发生火灾的报告后，立即派出专业救援队伍展开行动。获救人员均来自阿拉伯国家。救援人员在提供必要的急救措施后，已将他们移交给有关部门。 起火原因及船只受损情况尚未公布。"
