    "content": "新华社东京11月8日电（记者李子越 陈泽安）据日本广播协会报道，日本防卫大臣小泉进次郎8日在新潟县发表演讲时表示，将研究打破陆上、海上和航空自卫队之间传统界限的组织体制改革，以提升日本的“防卫力量”。 小泉称，在日本人口持续减少、确保足够数量的自卫队员日益困难的背景下，推动陆上、海上和航空自卫队实现真正意义上的一体化，是此次修订“安保三文件”的重点之一。他表示，对于能够打破以往界限、开展合作的领域，应进一步加强协作，推动自卫队组织体制改革。 日本政府拟于12月通过新版“安保三文件”。近期，日本政府持续强化所谓“防卫…"
