    "content": "最近在看《大明王朝 1566 》和《雍正王朝》，奏折、朱批看多了，就写了个小网站：选一位皇帝（嘉靖 / 康熙 / 雍正），用白话写你要奏的事，师爷帮你誊成文言奏折，封进折匣递上去，等皇帝亲笔批回来。 我跟嘉靖说这几天天气很好，他批： 讀了你的奏章，知道你體諒我修道的心意。但天道深奧，不是單純看天氣好就能理解的。你們應該更加謹慎，努力修煉道教儀式，來回應上天的恩賜。批准你的建議。 尽量照着史实做的几个地方： 竖排，自右向左，经折装。写到「皇上」「聖恩」就另起一行高出两格（抬头），自称的「臣」「奴才」写成小字偏在右边 …"
