    "content": "新华社沈阳11月8日电（记者叶新晨、武江民）11月7日14时至8日11时，辽宁西南部和大连中北部地区出现大雪到暴雪，局部大暴雪。受强降雪影响，部分高速路段限制特殊车辆驶入，葫芦岛市公交线路部分停运。辽宁各部门连夜开展除雪防滑作业，保障交通运行。 辽宁省气象部门数据显示，11月7日14时至8日11时，辽宁绥中两个气象站出现特大暴雪。多地降雪伴随大风天气，大连、鞍山、丹东、营口、葫芦岛、锦州等多地出现6级以上瞬时大风。 据辽宁省交通部门介绍，截至8日9时，全省普通干线公路累计投入除雪防滑队伍30支、人员1005人次。中…"
