    "description": "中国科学家在海南省发现一种全新的蛙类，命名为海南趾沟蛙。 据央视新闻报道，海南师范大学生命科学学院科研团队联合沈阳师范大学、中山大学在海南热带雨林国家公园发现两栖动物新物种——海南趾沟蛙，该研究成果发表于国际动物分类学期刊《ZooKeys》。 2024至2026年，研究团队在海南热带雨林国家公园吊罗山片区和海南省万宁市上溪省级自然保护区开展两栖动物野外调查，发现越南趾沟蛙种组物种个体。 经详细形态学比对研究，发现这些个体具有越南趾沟蛙种…",
    "content": "中国科学家在海南省发现一种全新的蛙类，命名为海南趾沟蛙。 据央视新闻报道，海南师范大学生命科学学院科研团队联合沈阳师范大学、中山大学在海南热带雨林国家公园发现两栖动物新物种——海南趾沟蛙，该研究成果发表于国际动物分类学期刊《ZooKeys》。 2024至2026年，研究团队在海南热带雨林国家公园吊罗山片区和海南省万宁市上溪省级自然保护区开展两栖动物野外调查，发现越南趾沟蛙种组物种个体。 经详细形态学比对研究，发现这些个体具有越南趾沟蛙种组的典型特征，但与该种组内其他已知物种存在明显差异，可能为一个尚未描述的新物种。…"
