    "description": "针对于 AI 编写可维护代码，是否有好的办法约束？或者沉淀自己的编码 skill 、agent? 如果让 ai 直接写代码，可能会是功能正常，代码一团乱？比如 过于冗杂的非空判断等 个人上下文的沉淀，如何让自己用 AI 时会不断地自我进化，而且不需要依赖单一的模型或者软件，这一份大脑是随着人的使用而成长 针对于工作上的代码和产品逻辑的维护，大家有没有经验可以分享的",
