    "description": "根据11月6日国际油价的收盘价格，纽约商品交易所12月交货的轻质原油期货价格报每桶90.83美元；2027年1月交货的伦敦布伦特原油期货价格报每桶98.32美元。美油期货主力合约价格一周下跌12.76%；布油期货主力合约价格一周下跌16.42%，创2020年以来最大跌幅。（央视财经）",
    "content": "根据11月6日国际油价的收盘价格，纽约商品交易所12月交货的轻质原油期货价格报每桶90.83美元；2027年1月交货的伦敦布伦特原油期货价格报每桶98.32美元。美油期货主力合约价格一周下跌12.76%；布油期货主力合约价格一周下跌16.42%，创2020年以来最大跌幅。（央视财经）"
