    "content": "意大利的蛤蜊、越南的腰果、韩国的柚子茶……徜徉在第九届中国国际进口博览会农食产品展区，仿佛走进了一座“世界宝库”。 今年进博会，农食产品展区专设300平方米的国际合作社产品与供应链展区，来自亚洲、欧洲、非洲、南美洲等地区的宝藏农产品琳琅满目。 在意大利戈罗渔业合作社的冰鲜海产展台上，刚刚空运抵沪的蛤蜊等海产品整齐陈列，吸引了采购商与观众驻足询价。 “中国消费者对高品质、原产地生鲜海产的需求非常旺盛，这让我们看到了巨大的市场潜力。”意大利戈罗渔业合作社负责人卢卡·曼格利尼告诉记者，“这是我们海产品在中国市场的首秀，依…"
