    "pub_date": "2026-11-08 14:22:43",
    "author": "",
    "description": "中国国家统计局调整内设机构，新设国情国力普查司、服务业和消费统计司等五个司。 据澎湃新闻报道，中国机构编制网公布了《国家统计局职能配置、内设机构和人员编制规定》（简称三定方案）。三定方案明确，中国国家统计局是中国国务院直属机构，为副部级。 据报道，相较此前，中国国家统计局内设机构有所调整。其中，国情国力普查司、生态环境和能源统计司、投资统计司、服务业和消费统计司、人口和民生统计司均为新设；此前的能源统计司、固定资产投资统计司、贸易外经统…",
    "content": "中国国家统计局调整内设机构，新设国情国力普查司、服务业和消费统计司等五个司。 据澎湃新闻报道，中国机构编制网公布了《国家统计局职能配置、内设机构和人员编制规定》（简称三定方案）。三定方案明确，中国国家统计局是中国国务院直属机构，为副部级。 据报道，相较此前，中国国家统计局内设机构有所调整。其中，国情国力普查司、生态环境和能源统计司、投资统计司、服务业和消费统计司、人口和民生统计司均为新设；此前的能源统计司、固定资产投资统计司、贸易外经统计司、人口和就业统计司、住户调查司不再保留。 新设的国情国力普查司负责拟订重大国…"
